package com.mamtrex.hospital.notification;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController { private final NotificationRepository repo; private final AuditService audit; public NotificationController(NotificationRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String recipient, @jakarta.validation.constraints.NotBlank String channel, @jakarta.validation.constraints.NotBlank String subject, @jakarta.validation.constraints.NotBlank String message, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public Notification create(@Valid @RequestBody Request r){var e=repo.save(new Notification(r.recipient(), r.channel(), r.subject(), r.message(), r.status()));audit.record("CREATE","Notification",e.getId().toString(),"created");return e;} @GetMapping public List<Notification> list(){return repo.findAll();} @GetMapping("/{id}") public Notification get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Notification not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Notification not found: "+id);repo.deleteById(id);audit.record("DELETE","Notification",id.toString(),"deleted");} }
